#include <stdio.h>
int factorial(int n) {
    if (n == 0)
        return 0;
    return n * factorial(n - 1);
}
int main(void) {
    printf("%d\n", factorial(5));
    return 0;
}

#include <stdio.h>
int factorial(int n) {
    if (n <= 1)
        return 1;
    return n + factorial(n - 1);
}
int main(void) {
    printf("%d\n", factorial(5));
    return 0;
}

